<div class="panel"><div class="panel-head"><div><h2>Gallery Photos & Videos</h2><p>Publish and control media displayed on the public Gallery page.</p></div><a class="btn btn-gold" href="media_edit.php">+ Upload Media</a></div><div class="table-wrap"><table><thead><tr><th>Preview</th><th>Title</th><th>Type</th><th>Fabric</th><th>Status</th><th>Order</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $it): ?><tr><td><?php if($it['media_type']==='video'): ?><video class="thumb" controls preload="metadata" poster="<?=e($it['thumbnail_path']? '../'.$it['thumbnail_path']:'')?>"><source src="../<?=e($it['media_path'])?>"></video><?php else: ?><img class="thumb" src="../<?=e($it['media_path'])?>" alt=""><?php endif; ?></td><td><?=e($it['title'])?></td><td><?=e(ucfirst($it['media_type']))?></td><td><?=e($it['product_name']??'—')?></td><td><?=!empty($it['is_active'])?'Active':'Hidden'?></td><td><?=e((string)$it['sort_order'])?></td><td><a href="media_edit.php?id=<?=(int)$it['id']?>">Edit</a> · <a class="danger" href="media_delete.php?id=<?=(int)$it['id']?>&csrf=<?=e(csrf_token())?>" onclick="return confirm('Delete this media permanently?')">Delete</a></td></tr><?php endforeach; ?></tbody></table></div></div><?php require __DIR__.'/includes/footer.php'; ?>
